// Extract the enriched findings array from the webhook body
const payload = $input.first().json;
const body = payload.body ?? payload;
const findings = Array.isArray(body) ? body : (body.findings ?? [body]);

// Only ticket-worthy findings: P1-CRITICAL or P2-HIGH (score >= 60)
const threshold = 60;

return findings
  .filter(f => (f.priority_score ?? 0) >= threshold)
  .map(f => ({ json: f }));

